import statsmodels.api as sm


def new_solution(df: pd.DataFrame, height: int, weight: int, columns: list) -> dict:
    """
    Perform an OLS linear regression for each dataset in the DataFrame,
    identified by the unique 'DatasetID' column.

    For each dataset:
      - Rows are filtered where the value in the second column of `columns`
        is greater than `height` AND the value in the third column of
        `columns` is less than `weight`.
      - The first column in `columns` is the dependent variable (y),
        and the remaining columns are the independent variables (X).
      - If the subset is empty, None is stored for that DatasetID.

    Parameters
    ----------
    df : pd.DataFrame
        DataFrame containing a 'DatasetID' column and the regression columns.
    height : int
        Threshold applied as `columns[1] > height`.
    weight : int
        Threshold applied as `columns[2] < weight`.
    columns : list
        List of column names: [target, feature_1, feature_2, ...].

    Returns
    -------
    dict
        Keys are 'DatasetID' values; values are fitted OLS results
        (statsmodels RegressionResults) or None if no matching rows.
    """
    if df is None or df.empty:
        return {}

    results = {}

    for dataset_id, group in df.groupby('DatasetID'):
        # Ensure the required columns exist in this subset
        if not all(col in group.columns for col in columns):
            results[dataset_id] = None
            continue

        # Filter rows: second column > height AND third column < weight
        subset = group[(group[columns[1]] > height) & (group[columns[2]] < weight)]

        # No matching rows -> None for this dataset
        if subset.empty:
            results[dataset_id] = None
            continue

        # Dependent variable: first column; Independent variables: the rest
        y = subset[columns[0]]
        X = subset[columns[1:]]

        # Add intercept and fit OLS regression
        X = sm.add_constant(X)
        model = sm.OLS(y, X)
        results[dataset_id] = model.fit()

    return results
